import * as React from "react";
import { loadGeoAsset } from "@/lib/map-basemap";

/**
 * Outlines of every country the catalogue offers, which the regions map shades for a cluster
 * placed in a whole country. Generated by scripts/regions/build_regions.py beside the catalogue,
 * from the outlines its country points are checked against; never edit the file by hand.
 */
// important: versioned like the basemap. /geo/* is cached immutable for a year, so changed
// content must ship under a new name or browsers keep the cached shapes.
export const COUNTRY_AREAS_URL = "/geo/country-areas.v1.json";

/** [south, west, north, east] around the country's main landmasses, which the map frames on. */
export type FocusBox = [number, number, number, number];

export type CountryArea = GeoJSON.Feature<GeoJSON.MultiPolygon, { focus: FocusBox }>;

/** ISO 3166-1 alpha-2 code to outline. */
export type CountryAreas = ReadonlyMap<string, CountryArea>;

function isFocusBox(value: unknown): value is FocusBox {
  return Array.isArray(value) && value.length === 4 && value.every((v) => Number.isFinite(v));
}

// A malformed feature is skipped rather than failing the file, so one bad country costs only
// its own shading.
function parseCountryAreas(data: unknown): CountryAreas {
  const features = (data as { features?: unknown })?.features;
  if (!Array.isArray(features)) throw new Error("Country outlines are not a FeatureCollection");
  const areas = new Map<string, CountryArea>();
  for (const feature of features as CountryArea[]) {
    if (
      typeof feature?.id === "string" &&
      feature.geometry?.type === "MultiPolygon" &&
      Array.isArray(feature.geometry.coordinates) &&
      feature.geometry.coordinates.length > 0 &&
      isFocusBox(feature.properties?.focus)
    ) {
      areas.set(feature.id, feature);
    }
  }
  return areas;
}

export function loadCountryAreas(): Promise<CountryAreas> {
  return loadGeoAsset(COUNTRY_AREAS_URL, parseCountryAreas);
}

export type CountryAreasStatus = "idle" | "loading" | "ready" | "failed";

/** Loads the outlines only once a whole-country region is on the map. */
export function useCountryAreas(enabled: boolean): { areas: CountryAreas | null; status: CountryAreasStatus } {
  const [areas, setAreas] = React.useState<CountryAreas | null>(null);
  const [failed, setFailed] = React.useState(false);

  React.useEffect(() => {
    if (!enabled || areas) return;
    let cancelled = false;
    setFailed(false);
    loadCountryAreas()
      .then((loaded) => {
        if (!cancelled) setAreas(loaded);
      })
      .catch(() => {
        if (!cancelled) setFailed(true);
      });
    return () => {
      cancelled = true;
    };
  }, [enabled, areas]);

  const status: CountryAreasStatus = areas ? "ready" : !enabled ? "idle" : failed ? "failed" : "loading";
  return { areas, status };
}
